// Original C++17 finite-strain directional-fiber kernel; standard library only.
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>
using V=std::vector<double>;using Clock=std::chrono::steady_clock;
struct Law{double buck,Y,H=.05,ls=.04,ds=.05;};
struct Q{double w,t,k,s,stored,diss;double kkt=0;};
Q elastic(double e,const Law&p){if(e<0&&p.buck>0){double x=e/p.buck,k=std::exp(x),t=p.buck*std::expm1(x),w=p.buck*p.buck*(std::expm1(x)-x);return{w,t,k,0,w,0};}if(e<=p.ls)return{.5*e*e,e,1,0,.5*e*e,0};double a=e-p.ls,x=a/p.ds,k=std::exp(x),t=p.ls+p.ds*std::expm1(x),w=.5*p.ls*p.ls+p.ls*a+p.ds*p.ds*(std::expm1(x)-x);return{w,t,k,0,w,0};}
Q response(double total,double old,const Law&p){if(p.Y<0)return elastic(total,p);Q q=elastic(total-old,p);if(q.t<=p.Y+p.H*old){q.s=old;q.w+=.5*p.H*old*old;q.stored=q.w;return q;}double e=(p.H*total+p.Y)/(1+p.H);for(int j=0;j<25;j++){Q t=elastic(e,p);double r=t.t+p.H*e-p.H*total-p.Y;if(std::abs(r)<1e-13)break;e-=r/(t.k+p.H);}double residual=elastic(e,p).t+p.H*e-p.H*total-p.Y;if(std::abs(residual)>1e-11*std::max(1.,std::abs(p.H*total+p.Y))){double lo=0,hi=std::max(0.,total-old);for(int k=0;k<70;k++){e=(lo+hi)/2;double r=elastic(e,p).t+p.H*e-p.H*total-p.Y;if(r>0)hi=e;else lo=e;}}double s=std::max(old,total-e);q=elastic(total-s,p);q.s=s;q.diss=p.Y*(s-old);q.stored=q.w+.5*p.H*s*s;q.w=q.stored+q.diss;q.k=q.k*p.H/(q.k+p.H);q.kkt=std::abs(q.t-p.H*s-p.Y);if(!(q.kkt<=1e-9*(1+std::abs(p.Y+p.H*s))))q.w=INFINITY;return q;}
struct Eval{double E=0,stored=0,diss=0,maxSlip=0,maxKKT=0;uint64_t slipped=0;V g,state;};
struct Model{uint32_t N,T,R;std::vector<int32_t>ids;V nodes,G,vol,dirs,C,diag,bc,linear;std::vector<uint8_t>fixed;Law law;double forceScale;
 template<class A>void read(std::ifstream&f,A&v,size_t n){v.resize(n);f.read(reinterpret_cast<char*>(v.data()),n*sizeof(typename A::value_type));if(!f)throw std::runtime_error("Truncated input");}
 Model(const std::string&file,Law l):law(l){std::ifstream f(file,std::ios::binary);char magic[8];f.read(magic,8);if(std::string(magic,8)!="FIBR0001")throw std::runtime_error("Bad input");f.read((char*)&N,4);f.read((char*)&T,4);f.read((char*)&R,4);if(N>1000000||T>10000000||R>1000)throw std::runtime_error("Input dimensions");read(f,ids,T*4ull);read(f,nodes,N*3ull);read(f,G,T*12ull);read(f,vol,T);read(f,dirs,R*4ull);read(f,C,T*R*4ull);read(f,diag,N*3ull);read(f,bc,N*3ull);read(f,linear,N*3ull);read(f,fixed,N);f.read((char*)&forceScale,8);if(!f)throw std::runtime_error("Missing force scale");for(auto i:ids)if(i<0||i>=N)throw std::runtime_error("Index");}
 double dot(const V&a,const V&b)const{double s=0;for(size_t i=0;i<a.size();i++)if(!fixed[i/3])s+=a[i]*b[i];return s;}
 Eval eval(const V&u,const V&old,bool state=false)const{Eval out;out.g.assign(N*3,0);if(state)out.state.resize(T*R);for(size_t e=0;e<T;e++){size_t id[4];for(int k=0;k<4;k++)id[k]=3*ids[e*4+k];double F[9]={1,0,0,0,1,0,0,0,1};for(int k=0;k<4;k++)for(int a=0;a<3;a++)for(int b=0;b<3;b++)F[a*3+b]+=u[id[k]+a]*G[e*12+3*k+b];double J=F[0]*(F[4]*F[8]-F[5]*F[7])-F[1]*(F[3]*F[8]-F[5]*F[6])+F[2]*(F[3]*F[7]-F[4]*F[6]);if(!(J>.05)){out.E=INFINITY;return out;}for(size_t r=0;r<R;r++){size_t ir=e*R+r,co=ir*4;double x=dirs[4*r],y=dirs[4*r+1],z=dirs[4*r+2],weight=15*vol[e]*dirs[4*r+3];for(int k=0;k<4;k++){double c=C[co+k];x+=u[id[k]]*c;y+=u[id[k]+1]*c;z+=u[id[k]+2]*c;}double L=std::sqrt(x*x+y*y+z*z);if(L<1e-8||!std::isfinite(L)){out.E=INFINITY;return out;}Q q=response(L-1,old.empty()?0:old[ir],law);if(!std::isfinite(q.w)||q.w>1e100){out.E=INFINITY;return out;}out.E+=weight*q.w;double a=weight*q.t/L;for(int k=0;k<4;k++){double b=a*C[co+k];out.g[id[k]]+=b*x;out.g[id[k]+1]+=b*y;out.g[id[k]+2]+=b*z;}if(state){out.state[ir]=q.s;out.stored+=weight*q.stored;out.diss+=weight*q.diss;out.maxSlip=std::max(out.maxSlip,q.s);out.maxKKT=std::max(out.maxKKT,q.kkt);if(q.s>1e-10)out.slipped++;}}}return out;}
 double minJ(const V&u)const{double min=INFINITY;for(size_t e=0;e<T;e++){double F[9]={1,0,0,0,1,0,0,0,1};for(int k=0;k<4;k++)for(int a=0;a<3;a++)for(int b=0;b<3;b++)F[a*3+b]+=u[3*ids[e*4+k]+a]*G[e*12+3*k+b];double J=F[0]*(F[4]*F[8]-F[5]*F[7])-F[1]*(F[3]*F[8]-F[5]*F[6])+F[2]*(F[3]*F[7]-F[4]*F[6]);min=std::min(min,J);}return min;}
 struct Solve{V u;Eval final;double relative;int iterations,evaluations,restarts;bool converged;};
 Solve solve(const V&b,const V&initial,const V&old,int maxit,double tol,double denominator)const{size_t D=N*3;V x=initial;for(size_t i=0;i<D;i++)if(fixed[i/3])x[i]=b[i];Eval q=eval(x,old);if(!std::isfinite(q.E))throw std::runtime_error("Invalid initial configuration");V g=q.g;double E=q.E;auto norm=[&](const V&v){return std::sqrt(dot(v,v))/std::max(denominator,1e-30);};double rel=norm(g);std::vector<V>S,Y;V rho;int it=0,evals=1,restarts=0;
 for(;it<maxit&&rel>tol;it++){V d=g,alpha(S.size());for(int k=int(S.size())-1;k>=0;k--){alpha[k]=rho[k]*dot(S[k],d);for(size_t i=0;i<D;i++)if(!fixed[i/3])d[i]-=alpha[k]*Y[k][i];}double scale=1;if(!S.empty()){auto k=S.size()-1;double sy=dot(S[k],Y[k]),yy=0;for(size_t i=0;i<D;i++)if(!fixed[i/3])yy+=Y[k][i]*Y[k][i]/diag[i];scale=std::clamp(sy/std::max(yy,1e-30),.001,1000.);}for(size_t i=0;i<D;i++)d[i]=fixed[i/3]?0:d[i]*scale/diag[i];for(size_t k=0;k<S.size();k++){double beta=rho[k]*dot(Y[k],d);for(size_t i=0;i<D;i++)if(!fixed[i/3])d[i]+=S[k][i]*(alpha[k]-beta);}for(auto&v:d)v=-v;double gd=dot(g,d);if(!(gd<0)){for(size_t i=0;i<D;i++)d[i]=fixed[i/3]?0:-g[i]/diag[i];gd=dot(g,d);S.clear();Y.clear();rho.clear();restarts++;}double step=1;V nx(D);Eval nq;bool accept=false;for(int ls=0;ls<32;ls++){for(size_t i=0;i<D;i++)nx[i]=fixed[i/3]?b[i]:x[i]+step*d[i];nq=eval(nx,old);evals++;double round=64*std::numeric_limits<double>::epsilon()*std::max(1.,std::abs(E));if(std::isfinite(nq.E)&&(nq.E<=E+1e-4*step*gd||(nq.E<=E+round&&norm(nq.g)<rel*.999))){accept=true;break;}step*=.5;}if(!accept){S.clear();Y.clear();rho.clear();restarts++;if(restarts>12)break;continue;}V s(D),y(D);for(size_t i=0;i<D;i++)if(!fixed[i/3]){s[i]=nx[i]-x[i];y[i]=nq.g[i]-g[i];}double sy=dot(s,y);if(sy>1e-12*std::sqrt(dot(s,s)*dot(y,y))){S.push_back(std::move(s));Y.push_back(std::move(y));rho.push_back(1/sy);if(S.size()>15){S.erase(S.begin());Y.erase(Y.begin());rho.erase(rho.begin());}}x=std::move(nx);g=std::move(nq.g);E=nq.E;rel=norm(g);}
 Eval final=eval(x,old,true);rel=norm(final.g);return{std::move(x),std::move(final),rel,it,evals,restarts,rel<=tol&&std::isfinite(final.E)};}
};
void binary(const std::string&p,const V&v){std::ofstream f(p,std::ios::binary);f.write((const char*)v.data(),v.size()*8);if(!f)throw std::runtime_error("Output error");}
int main(int argc,char**argv){try{if(argc<6)throw std::runtime_error("input outputprefix buckling yield steps [maxiterations]");Law law{std::stod(argv[3]),std::stod(argv[4])};Model m(argv[1],law);std::string prefix=argv[2];int steps=std::stoi(argv[5]),maxit=argc>6?std::stoi(argv[6]):3000;auto start=Clock::now();
 if(steps==0){V u(m.N*3);std::ifstream f(prefix+".probe-u.bin",std::ios::binary);f.read((char*)u.data(),u.size()*8);if(!f)throw std::runtime_error("probe input missing");V previous;std::ifstream previousFile(prefix+".probe-prev.bin",std::ios::binary);if(previousFile){previous.resize(m.T*m.R);previousFile.read((char*)previous.data(),previous.size()*8);if(!previousFile)throw std::runtime_error("Bad probe previous state");}Eval q=m.eval(u,previous);binary(prefix+".probe-g.bin",q.g);std::cout<<std::setprecision(17)<<"{\"energy\":"<<q.E<<"}"<<std::endl;return 0;}
 V u(m.N*3,0),old,prevG(m.N*3,0);double cumulativeD=0,work=0;std::ofstream log(prefix+".csv");log<<"step,fraction,converged,relative,iterations,evaluations,restarts,potential,stored,increment_diss,cumulative_diss,work,relative_balance,minJ,slipped,max_slip,max_kkt,seconds\n";for(int step=1;step<=steps;step++){double a=double(step)/steps;V b(m.N*3),initial(u.size());for(size_t i=0;i<u.size();i++){b[i]=a*m.bc[i];initial[i]=u[i]+m.linear[i]/steps;} // kinematic warm start depends on boundary data only
 // Fixed reference scale uses linear operator energy normalization reconstructed from displacement-boundary reactions via the no-buckling tangent proxy.
 double denominator=a*m.forceScale;
 if(step==steps)binary(prefix+".previous-state.bin",old);auto r=m.solve(b,initial,old,maxit,1e-7,denominator);double J=m.minJ(r.u);r.converged=r.converged&&J>.05;if(!r.converged){log<<step<<","<<a<<",0,"<<r.relative<<","<<r.iterations<<","<<r.evaluations<<","<<r.restarts<<","<<r.final.E<<","<<r.final.stored<<","<<r.final.diss<<","<<cumulativeD<<","<<work<<",nan,"<<J<<","<<r.final.slipped<<","<<r.final.maxSlip<<","<<r.final.maxKKT<<","<<std::chrono::duration<double>(Clock::now()-start).count()<<std::endl;binary(prefix+".failed-u.bin",r.u);std::cerr<<"FAILED step "<<step<<" residual "<<r.relative<<" minJ "<<J<<std::endl;return 2;}
 for(size_t i=0;i<u.size();i++)if(m.fixed[i/3])work+=(prevG[i]+r.final.g[i])*.5*m.bc[i]/steps;cumulativeD+=r.final.diss;double balance=std::abs(work-r.final.stored-cumulativeD)/std::max({std::abs(work),std::abs(r.final.stored)+cumulativeD,1e-30});u=std::move(r.u);old=std::move(r.final.state);prevG=std::move(r.final.g);double seconds=std::chrono::duration<double>(Clock::now()-start).count();log<<std::setprecision(17)<<step<<","<<a<<",1,"<<r.relative<<","<<r.iterations<<","<<r.evaluations<<","<<r.restarts<<","<<r.final.E<<","<<r.final.stored<<","<<r.final.diss<<","<<cumulativeD<<","<<work<<","<<balance<<","<<J<<","<<r.final.slipped<<","<<r.final.maxSlip<<","<<r.final.maxKKT<<","<<seconds<<std::endl;binary(prefix+".u.bin",u);binary(prefix+".state.bin",old);std::cout<<"STEP "<<step<<"/"<<steps<<" residual "<<r.relative<<" it "<<r.iterations<<" balance "<<balance<<" seconds "<<seconds<<std::endl;}
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
